  function uploadCustomFont(){ const input = $('fontFileInput'), button = $('fontUploadSubmit'); const file = input && input.files ? input.files[0] : null; if(!FONT_API.loggedIn){ setUploadStatus('Login diperlukan untuk upload font.', 'error', true); return; } if(!file){ setUploadStatus('Pilih file font terlebih dahulu.', 'error'); return; } const body = new FormData(); body.set('font_file', file); if(button) button.disabled = true; setUploadStatus('Mengupload dan memvalidasi font...'); fontApi('flamo_temp_font_upload', body).then(data => { if(input) input.value = ''; setUploadStatus(data.message || 'Font berhasil diupload.', 'success'); return loadCustomFonts(data.font && data.font.id ? 'custom:' + data.font.id : '').then(() => { if(data.font && data.font.id && $('fontName')) $('fontName').value = 'custom:' + data.font.id; renderFontStyleOptions(''); if (typeof updateAll === 'function') updateAll(); if (typeof renderAll === 'function') renderAll(); if (typeof markDirty === 'function') markDirty(); if (typeof notifyDirty === 'function') notifyDirty(); }); }).catch(error => setUploadStatus(error.message, 'error')).finally(() => { if(button) button.disabled = false; }); }
