  function b64decode(data){ const bin=atob(data); const bytes=Uint8Array.from(bin, c=>c.charCodeAt(0)); if(window.TextDecoder) return new TextDecoder('utf-8').decode(bytes); return decodeURIComponent(escape(bin)); }

  function availableFontStyles(fontName){ if(isCustomFont(fontName)) return ['']; const raw=FONT_STYLE_MAP[String(fontName||'Lexend').trim()] || ['400']; return raw.map(String).filter(v=>FONT_LABEL[v]); }
