  function normalizeText(raw){
    raw=String(raw||'flamo creative').replace(/\r/g,'').trim(); if(!raw) raw='flamo creative';
    const rawLines=raw.split('\n').map(x=>x.trim()).filter(Boolean);
    if(rawLines.length>=2){ const a=rawLines[0].split(/\s+/).slice(0,2).join(' '); const b=rawLines[1].split(/\s+/).slice(0,2).join(' '); return b ? a+'\n'+b : a; }
    const words=(rawLines[0]||raw).split(/\s+/).filter(Boolean).slice(0,4); if(words.length<=2) return words.join(' ')||'flamo creative'; return words.slice(0,2).join(' ')+'\n'+words.slice(2,4).join(' ');
  }
  function updateFilename(force=false){ if(state.filenameTouched&&!force)return; const p=getPreset(); const first=(normalizeText($('inputText').value).split('\n')[0]||'flamo'); $('filename').value=slug(first)+'#'+p.slug; }
